script:
// Medical Center Navigator.
// `root_element` is the shadow root, injected by frappe.create_shadow_element.
// Routing goes through frappe.set_route rather than <a href>, because a click
// inside a shadow tree is retargeted before it reaches the desk router, so a
// plain link would trigger a full page reload.

// The live operations dashboard (digitz_erp/digitz_erp/page/
// medical_center_dashboard). Set to null to make the button explain that the
// dashboard is unavailable rather than routing to a 404.
const DASHBOARD_ROUTE = ["Medical Center Dashboard"];

root_element.addEventListener("click", function (event) {
    const card = event.target.closest("[data-route]");

    if (card) {
        let route;
        try {
            route = JSON.parse(card.getAttribute("data-route"));
        } catch (e) {
            return;
        }
        frappe.set_route.apply(null, route);
        return;
    }

    if (event.target.closest('[data-action="dashboard"]')) {
        if (DASHBOARD_ROUTE) {
            frappe.set_route.apply(null, DASHBOARD_ROUTE);
        } else {
            frappe.show_alert(
                {
                    message: __("The Medical Center dashboard is not available."),
                    subtitle: __("Run bench migrate to install the dashboard page."),
                    indicator: "orange",
                },
                5
            );
        }
    }
});

// Cards are <button> elements, so Enter and Space already activate them.

style:
/* Medical Center Navigator.
   Rendered inside a shadow root, so desk.bundle.css is linked in but its
   :root block does not apply. Frappe's CSS custom properties still reach us
   by inheritance through the shadow host, which is what makes this follow the
   light/dark theme without any extra work.

   --tone / --tone-2 are set per card and per section as inline style
   attributes (style ATTRIBUTES survive frappe.dom.remove_script_and_style;
   <style> TAGS do not), so one rule set drives twelve different accents.
   --tag / --tag-2 do the same for the four kinds of stamp. */

.mc-nav {
  --mc-gap: 14px;
  font-family: var(--font-stack, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif);
  color: var(--text-color, #1f272e);
  padding: 2px;
}

.mc-nav *, .mc-nav *::before, .mc-nav *::after { box-sizing: border-box; }

/* ---------- hero ---------- */

.mc-hero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  padding: 22px 24px;
  margin-bottom: 24px;
  border: 1px solid var(--border-color, #e2e6e9);
  border-radius: var(--border-radius-lg, 10px);
  background:
    radial-gradient(105% 150% at 100% 0%, rgba(168, 85, 247, 0.26) 0%, rgba(168, 85, 247, 0) 58%),
    radial-gradient(95% 140% at 62% 120%, rgba(236, 72, 153, 0.20) 0%, rgba(236, 72, 153, 0) 60%),
    radial-gradient(85% 130% at 0% 100%, rgba(14, 165, 233, 0.26) 0%, rgba(14, 165, 233, 0) 62%),
    var(--card-bg, var(--fg-color, #fff));
}

/* bright rule across the top of the hero */
.mc-hero::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, #0ea5e9, #8b5cf6 38%, #ec4899 68%, #f97316);
}

.mc-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: linear-gradient(90deg, #0ea5e9, #8b5cf6);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin-bottom: 5px;
}

.mc-hero h2 {
  margin: 0 0 6px;
  font-size: 22px;
  font-weight: 750;
  line-height: 1.2;
  letter-spacing: -0.015em;
  color: var(--heading-color, var(--text-color, #1f272e));
}

.mc-hero p {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-muted, #8d99a6);
  max-width: 52ch;
}

.mc-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border: none;
  border-radius: var(--border-radius-md, 8px);
  background: linear-gradient(135deg, #6366f1, #a855f7 55%, #ec4899);
  color: #fff;
  font-size: 13px;
  font-weight: 650;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.14s ease, box-shadow 0.14s ease, filter 0.14s ease;
  box-shadow: 0 4px 14px -3px rgba(168, 85, 247, 0.55);
}

.mc-cta:hover { filter: brightness(1.08); box-shadow: 0 7px 20px -3px rgba(168, 85, 247, 0.7); }
.mc-cta:active { transform: translateY(1px); }
.mc-cta:focus-visible { outline: 2px solid #a855f7; outline-offset: 2px; }
.mc-cta .mc-cta-arrow { transition: transform 0.14s ease; }
.mc-cta:hover .mc-cta-arrow { transform: translateX(3px); }

/* ---------- sections ---------- */

.mc-section { margin-bottom: 26px; }
.mc-section:last-child { margin-bottom: 4px; }

.mc-sec-head {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  padding-bottom: 9px;
  margin-bottom: 14px;
  border-bottom: 1px solid var(--border-color, #e2e6e9);
}

.mc-sec-bar {
  width: 4px;
  height: 15px;
  border-radius: 3px;
  background: linear-gradient(180deg, var(--tone), var(--tone-2));
  flex: none;
}

.mc-sec-head h3 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--heading-color, var(--text-color, #1f272e));
}

.mc-sec-count {
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, var(--tone), var(--tone-2));
  border-radius: 999px;
  padding: 2px 8px;
  min-width: 21px;
  text-align: center;
  line-height: 1.45;
}

.mc-sec-blurb {
  font-size: 12px;
  color: var(--text-muted, #8d99a6);
}

/* ---------- cards ---------- */

.mc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(248px, 1fr));
  gap: var(--mc-gap);
}

.mc-card {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  text-align: left;
  gap: 9px;
  padding: 15px 15px 13px;
  font: inherit;
  color: inherit;
  cursor: pointer;
  /* Solid at rest, in the card's own hue, so every card is distinct without
     needing hover. --tone-soft is a precomputed rgba: CSS cannot add alpha to
     a hex custom property without color-mix(), which is newer than the
     browsers this desk has to support. */
  border: 1px solid var(--tone-soft, var(--border-color, #e2e6e9));
  border-radius: var(--border-radius-md, 8px);
  background: var(--card-bg, var(--fg-color, #fff));
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

/* accent rail, in the card's own hue, that sweeps in on hover */
.mc-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, var(--tone), var(--tone-2));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.22s ease;
}

.mc-card:hover, .mc-card:focus-visible {
  transform: translateY(-3px);
  border-color: var(--tone);
  box-shadow: 0 10px 24px -10px var(--tone);
}

.mc-card:hover::before, .mc-card:focus-visible::before { transform: scaleX(1); }
.mc-card:active { transform: translateY(-1px); }
.mc-card:focus-visible { outline: 2px solid var(--tone); outline-offset: 2px; }

.mc-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

/* per-destination hue, solid gradient with a white glyph */
.mc-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  flex: none;
  color: #fff;
  background: linear-gradient(135deg, var(--tone), var(--tone-2));
  box-shadow: 0 3px 9px -3px var(--tone);
}

/* per-kind hue: what this card opens */
.mc-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #fff;
  background: linear-gradient(135deg, var(--tag), var(--tag-2));
  border-radius: 999px;
  padding: 3px 9px 3px 7px;
  white-space: nowrap;
  box-shadow: 0 2px 6px -2px var(--tag);
}

.mc-card-title {
  font-size: 13.5px;
  font-weight: 650;
  line-height: 1.3;
  color: var(--heading-color, var(--text-color, #1f272e));
}

.mc-card-sum {
  margin: 0;
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-muted, #8d99a6);
  flex: 1 1 auto;
}

.mc-open {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--tone);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.mc-card:hover .mc-open,
.mc-card:focus-visible .mc-open { opacity: 1; transform: translateX(0); }

/* ---------- icons ---------- */

.mc-ic { width: 19px; height: 19px; flex: none; }
.mc-ic-sm { width: 15px; height: 15px; }
.mc-ic-xs { width: 12px; height: 12px; }

/* ---------- responsive ---------- */

@media (max-width: 640px) {
  .mc-grid { grid-template-columns: 1fr; }
  .mc-hero { padding: 18px; }
  .mc-cta { width: 100%; justify-content: center; }
  .mc-open { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mc-card, .mc-cta, .mc-open, .mc-cta-arrow, .mc-card::before { transition: none; }
  .mc-card:hover { transform: none; }
}
